Nq = 18.4
Ngam = 22.4
Fqs = dec(1 + (Bef/Lef)*tan(30*pi/180), 3)
Fgs = dec(1 - 0.4*(Bef/Lef), 3)
Fqd = dec(1 + 2*tan(30*pi/180)*(1 - sin(30*pi/180))^2*0.7/Bd, 3)
Qu = dec(Aef*(qs*Nq*Fqs*Fqd + 0.5*18*Bef*Ngam*Fgs), 0)
